<?php $selectedJob=$request->query['job']??($data['items'][0]['id']??null);$applications=$selectedJob?$app->api('applications/job/'.$selectedJob):[];$stages=['APPLIED'=>'Đã ứng tuyển','AI_SCREENING'=>'AI đánh giá','HR_REVIEW'=>'HR xem xét','INTERVIEW'=>'Phỏng vấn','OFFER'=>'Đề nghị','HIRED'=>'Đã tuyển','REJECTED'=>'Từ chối'];$scores=array_map(function($a){return (float)($a['aiResult']['overallScore']??0);},$applications);$stats=['Ứng viên'=>count($applications),'Avg AI Score'=>$scores?round(array_sum($scores)/count($scores),1):0,'Interview+'=>count(array_filter($applications,function($a){return in_array($a['status'],['INTERVIEW','OFFER'],true);})), 'Jobs active'=>count(array_filter($data['items'],function($j){return $j['status']==='ACTIVE';}))]; ?>
<div class="stat-cards recruiter-stats section"><?php foreach($stats as $label=>$value): ?><section class="panel"><span class="muted"><?= e($label) ?></span><strong><?= e($value) ?></strong></section><?php endforeach; ?></div>
<section class="panel section"><div class="grid recruiter-filters"><form><label>Tin tuyển dụng<select name="job" onchange="this.form.requestSubmit()"><?php foreach($data['items'] as $j): ?><option value="<?= e($j['id']) ?>" <?= $selectedJob===$j['id']?'selected':'' ?>><?= e($j['title']) ?> · <?= e($j['company']['name']) ?></option><?php endforeach; ?></select></label></form><label>Tìm ứng viên<input id="candidate-search" placeholder="Tên hoặc email..."></label><label>Trạng thái<select id="candidate-status"><option value="">Tất cả</option><?php foreach($stages as $stage=>$label): ?><option value="<?= e($stage) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label><label>Sắp xếp<select id="candidate-sort"><option value="score">AI Score cao → thấp</option><option value="date">Mới nhất</option></select></label></div><?php if($selectedJob): ?><div class="row section"><a class="button ghost" href="/api/v1/applications/job/<?= e($selectedJob) ?>/export">Export CSV</a></div><?php endif; ?></section>
<section class="panel section table-scroll"><table id="candidate-table"><thead><tr><th>Ứng viên</th><th>Status</th><th>AI Score</th><th>Actions</th></tr></thead><tbody><?php foreach($applications as $a): ?><tr data-candidate data-status="<?= e($a['status']) ?>" data-score="<?= e($a['aiResult']['overallScore']??0) ?>" data-date="<?= e($a['appliedAt']) ?>"><td><strong><?= e($a['candidate']['profile']['fullName']??'') ?></strong><p class="muted"><?= e($a['candidate']['email']) ?></p></td><td><span class="status-badge status-<?= e($a['status']) ?>"><?= e($stages[$a['status']]??$a['status']) ?></span></td><td><strong class="positive"><?= e($a['aiResult']['overallScore']??'—') ?></strong></td><td><div class="row"><a class="button ghost" href="/applications/<?= e($a['id']) ?>">Chi tiết</a><button class="ghost" data-action="/applications/<?= e($a['id']) ?>/rescreen">Re-screen</button><select aria-label="Trạng thái ứng viên" <?= in_array($a['status'],['HIRED','REJECTED','WITHDRAWN'],true)?'disabled':'' ?> data-application-status="<?= e($a['id']) ?>" data-current-status="<?= e($a['status']) ?>"><?php foreach($stages as $stage=>$label): ?><option value="<?= e($stage) ?>" <?= $a['status']===$stage?'selected':'' ?> <?= in_array($stage,['APPLIED','AI_SCREENING'],true)?'disabled':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div></td></tr><?php endforeach; ?></tbody></table><?php if(!$applications): ?><div class="empty"><h2>Chưa có ứng viên</h2><p class="muted">Hồ sơ ứng tuyển sẽ xuất hiện tại đây.</p></div><?php endif; ?></section>
<section class="panel section"><h2>Pipeline board</h2><div class="kanban-board section"><?php foreach($stages as $stage=>$label): ?><div class="kanban-column"><h3><?= e($label) ?> <span class="badge"><?= count(array_filter($applications,function($a)use($stage){return $a['status']===$stage;})) ?></span></h3><?php foreach($applications as $a):if($a['status']!==$stage)continue; ?><article class="kanban-candidate" data-candidate data-status="<?= e($a['status']) ?>"><a href="/applications/<?= e($a['id']) ?>"><?= e($a['candidate']['profile']['fullName']??'') ?></a><p class="muted"><?= e($a['candidate']['email']) ?></p><p class="positive">AI <?= e($a['aiResult']['overallScore']??'—') ?></p><select aria-label="Chuyển trạng thái ứng viên" <?= in_array($a['status'],['HIRED','REJECTED','WITHDRAWN'],true)?'disabled':'' ?> data-application-status="<?= e($a['id']) ?>" data-current-status="<?= e($a['status']) ?>"><?php foreach($stages as $v=>$l): ?><option value="<?= e($v) ?>" <?= $v===$stage?'selected':'' ?> <?= in_array($v,['APPLIED','AI_SCREENING'],true)?'disabled':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></article><?php endforeach; ?></div><?php endforeach; ?></div></section>